class Customer extends DataClass implements Insertable<Customer> {
  final String id;

  /// Nullable *and* unique, deliberately: SQLite counts every NULL as
  /// distinct, so this reads as "at most one row per SAP id, and rows without
  /// one never conflict" — which is exactly the rule for field-created
  /// customers awaiting approval.
  final String? sapCustomerId;
  final String customerCode;
  final String shopName;
  final String ownerName;
  final String phone;
  final String? email;
  final String? whatsapp;
  final String address;
  final String province;
  final String district;
  final String territory;
  final double latitude;
  final double longitude;
  final double creditLimit;
  final String status;
  final String assignedRepId;
  final String assignedRepName;
  final DateTime updatedAt;
  final String? originLeadId;
  final String productsPurchased;
  final DateTime? lastOrderDate;
  final DateTime? lastVisitDate;
  final double lifetimeValue;
  final int openOpportunityCount;
  final bool deleted;

  /// Urban / rural / etc. — drives visit-planning rules.
  final String? territoryType;

  /// Per-customer geofence radius in metres, overriding the global policy when
  /// a site is unusually large (a depot yard) or tight (a stall in a market).
  final double? geofenceRadiusOverride;

  /// Sales area — the three fields SAP uses together to scope a customer.
  final String? salesOrg;
  final String? division;
  final String? distributionChannel;

  /// Commercial classification.
  final String? customerGroup;
  final String? priceGroup;

  /// Latin and Khmer legal names. `shopName` stays the display name; these are
  /// the SAP `name1` / `name3` equivalents used for search and documents.
  final String? enName;
  final String? khName;

  /// Credit position. `creditLimit` already exists above; the balance is the
  /// currently-consumed portion, so available credit is limit − balance.
  final double creditBalance;
  final String currency;

  /// VAT / tax identification number (SAP `taxNumber`).
  final String? taxNumber;

  /// Lifetime order count. `lifetimeValue` above is the matching money figure.
  final int totalOrders;

  /// When SAP first created the record. `updatedAt` already covers the
  /// modification side.
  final DateTime? createdAt;

  /// Per-row sync state — `synced` / `dirty` / `syncing` / `conflict`
  /// (SYNC_ENGINE.md §5). Adding it here closes part of the standard
  /// syncable-column gap in DATABASE_GUIDE.md §3.1; `server_revision` and
  /// `dirty` remain outstanding and belong with the sync-engine work rather
  /// than this feature change.
  final String syncState;
  const Customer(
      {required this.id,
      this.sapCustomerId,
      required this.customerCode,
      required this.shopName,
      required this.ownerName,
      required this.phone,
      this.email,
      this.whatsapp,
      required this.address,
      required this.province,
      required this.district,
      required this.territory,
      required this.latitude,
      required this.longitude,
      required this.creditLimit,
      required this.status,
      required this.assignedRepId,
      required this.assignedRepName,
      required this.updatedAt,
      this.originLeadId,
      required this.productsPurchased,
      this.lastOrderDate,
      this.lastVisitDate,
      required this.lifetimeValue,
      required this.openOpportunityCount,
      required this.deleted,
      this.territoryType,
      this.geofenceRadiusOverride,
      this.salesOrg,
      this.division,
      this.distributionChannel,
      this.customerGroup,
      this.priceGroup,
      this.enName,
      this.khName,
      required this.creditBalance,
      required this.currency,
      this.taxNumber,
      required this.totalOrders,
      this.createdAt,
      required this.syncState});
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    if (!nullToAbsent || sapCustomerId != null) {
      map['sap_customer_id'] = Variable<String>(sapCustomerId);
    }
    map['customer_code'] = Variable<String>(customerCode);
    map['shop_name'] = Variable<String>(shopName);
    map['owner_name'] = Variable<String>(ownerName);
    map['phone'] = Variable<String>(phone);
