class Product extends DataClass implements Insertable<Product> {
  final String id;
  final String familyId;
  final String familyName;
  final String code;
  final String sku;
  final String materialCode;
  final String barcode;

  /// SAP `MaterialDes`.
  final String name;

  /// SAP `MaterialDesKH`. Defaulted rather than nullable so every read gets a
  /// string and the fallback lives in one place ([LocalizedText.resolve]).
  final String nameKh;
  final String description;

  /// Top colour / finish — the last thing a roofing customer chooses, and
  /// distinct from `grade`.
  final String color;

  /// Free-text spec for rows the structured dimension columns don't fully
  /// describe.
  final String specification;
  final String categoryId;
  final String subCategory;
  final String brand;
  final String grade;
  final String material;
  final String size;
  final double diameter;
  final double thickness;
  final double length;
  final double width;
  final double height;
  final double weight;
  final String unit;
  final String warehouseCode;
  final String territory;
  final String businessUnit;
  final String imageUrl;
  final bool isMto;
  final String status;
  final DateTime updatedAt;

  /// SAP creation date. Nullable — the current extract doesn't carry it for
  /// every material, and a fabricated date would be worse than a null.
  final DateTime? createdAt;
  final bool deleted;
  final double minStock;
  final double maxStock;
  const Product(
      {required this.id,
      required this.familyId,
      required this.familyName,
      required this.code,
      required this.sku,
      required this.materialCode,
      required this.barcode,
      required this.name,
      required this.nameKh,
      required this.description,
      required this.color,
      required this.specification,
      required this.categoryId,
      required this.subCategory,
      required this.brand,
      required this.grade,
      required this.material,
      required this.size,
      required this.diameter,
      required this.thickness,
      required this.length,
      required this.width,
      required this.height,
      required this.weight,
      required this.unit,
      required this.warehouseCode,
      required this.territory,
      required this.businessUnit,
      required this.imageUrl,
      required this.isMto,
      required this.status,
      required this.updatedAt,
      this.createdAt,
      required this.deleted,
      required this.minStock,
      required this.maxStock});
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['family_id'] = Variable<String>(familyId);
    map['family_name'] = Variable<String>(familyName);
    map['code'] = Variable<String>(code);
    map['sku'] = Variable<String>(sku);
    map['material_code'] = Variable<String>(materialCode);
    map['barcode'] = Variable<String>(barcode);
    map['name'] = Variable<String>(name);
    map['name_kh'] = Variable<String>(nameKh);
    map['description'] = Variable<String>(description);
    map['color'] = Variable<String>(color);
    map['specification'] = Variable<String>(specification);
    map['category_id'] = Variable<String>(categoryId);
    map['sub_category'] = Variable<String>(subCategory);
    map['brand'] = Variable<String>(brand);
    map['grade'] = Variable<String>(grade);
    map['material'] = Variable<String>(material);
    map['size'] = Variable<String>(size);
    map['diameter'] = Variable<double>(diameter);
    map['thickness'] = Variable<double>(thickness);
    map['length'] = Variable<double>(length);
    map['width'] = Variable<double>(width);
    map['height'] = Variable<double>(height);
    map['weight'] = Variable<double>(weight);
    map['unit'] = Variable<String>(unit);
    map['warehouse_code'] = Variable<String>(warehouseCode);
    map['territory'] = Variable<String>(territory);
    map['business_unit'] = Variable<String>(businessUnit);
    map['image_url'] = Variable<String>(imageUrl);
    map['is_mto'] = Variable<bool>(isMto);
    map['status'] = Variable<String>(status);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || createdAt != null) {
      map['created_at'] = Variable<DateTime>(createdAt);
    }
    map['deleted'] = Variable<bool>(deleted);
    map['min_stock'] = Variable<double>(minStock);
    map['max_stock'] = Variable<double>(maxStock);
    return map;
  }

